struct RingBuffer {
    RingBuffer(int capacity) : head(0), count(0), cap(capacity) {}

    bool push(int value) {
        if (full()) return false;
        data[(head + count) % cap] = value;
        ++count;
        return true;
    }

    bool pop(int& out) {
        if (empty()) return false;
        out = data[head];
        head = (head + 1) % cap;
        --count;
        return true;
    }

    int size() const { return count; }
    bool empty() const { return count == 0; }
    bool full() const { return count == cap; }

private:
    int data[1024];
    int head;
    int count;
    int cap;
};
