__global__ void block_sum(const float* in, float* out, int n)
{
    extern __shared__ float sdata[];

    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + tid;

    float val = 0.0f;
    if (idx < n) {
        val = in[idx];
    }
    sdata[tid] = val;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sdata[tid] += sdata[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        out[blockIdx.x] = sdata[0];
    }
}

double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad) {
    const int nW1 = n_hidden * n_in;
    const double* W1 = params;
    const double* b1 = params + nW1;
    const double* W2 = b1 + n_hidden;
    const double b2 = *W2;
    double* gW1 = grad;
    double* gb1 = gW1 + nW1;
    double* gW2 = gb1 + n_hidden;
    double* gb2 = gW2;

    for (int i = 0; i < nW1 + n_hidden + n_hidden + 1; ++i) grad[i] = 0.0;

    double loss = 0.0;
    for (int s = 0; s < n_samples; ++s) {
        const double* x = X + (long)s * n_in;
        double h[1024];
        // hidden layer
        for (int j = 0; j < n_hidden; ++j) {
            double a = b1[j];
            for (int k = 0; k < n_in; ++k) a += W1[j * n_in + k] * x[k];
            h[j] = std::tanh(a);
        }
        double z = b2;
        for (int j = 0; j < n_hidden; ++j) z += W2[j] * h[j];
        double p = 1.0 / (1.0 + std::exp(-z));
        double yy = y[s];
        loss += -(yy * std::log(p) + (1.0 - yy) * std::log(1.0 - p));
        double dz = (p - yy); // d loss / dz for this sample
        for (int j = 0; j < n_hidden; ++j) {
            gW2[j] += dz * h[j];
            double dh = dz * W2[j] * (1.0 - h[j] * h[j]);
            for (int k = 0; k < n_in; ++k) gW1[j * n_in + k] += dh * x[k];
            gb1[j] += dh;
        }
        *gb2 += dz;
    }
    double inv = 1.0 / n_samples;
    for (int i = 0; i < nW1 + n_hidden + n_hidden + 1; ++i) grad[i] *= inv;
    return loss * inv;
}

struct Tape {
    struct Node { double v; double g; int a, b; char op; bool isInput; };
    std::vector<Node> nodes;

    int constant(double v){ nodes.push_back({v,0.0,-1,-1,0,false}); return (int)nodes.size()-1; }
    int input(double v){ nodes.push_back({v,0.0,-1,-1,0,true}); return (int)nodes.size()-1; }
    int add(int a,int b){ nodes.push_back({nodes[a].v+nodes[b].v,0.0,a,b,1,false}); return (int)nodes.size()-1; }
    int mul(int a,int b){ nodes.push_back({nodes[a].v*nodes[b].v,0.0,a,b,2,false}); return (int)nodes.size()-1; }
    int sin_(int a){ nodes.push_back({std::sin(nodes[a].v),0.0,a,-1,3,false}); return (int)nodes.size()-1; }
    int exp_(int a){ nodes.push_back({std::exp(nodes[a].v),0.0,a,-1,4,false}); return (int)nodes.size()-1; }

    double value(int node) const { return nodes[node].v; }

    void backward(int root){
        for (auto& n : nodes) n.g = 0.0;
        nodes[root].g = 1.0;
        for (int i = (int)nodes.size()-1; i >= 0; --i){
            Node& n = nodes[i];
            if (n.g == 0.0) continue;
            switch (n.op){
                case 1:
                    nodes[n.a].g += n.g;
                    nodes[n.b].g += n.g;
                    break;
                case 2:
                    nodes[n.a].g += n.g * nodes[n.b].v;
                    nodes[n.b].g += n.g * nodes[n.a].v;
                    break;
                case 3:
                    nodes[n.a].g += n.g * std::cos(nodes[n.a].v);
                    break;
                case 4:
                    nodes[n.a].g += n.g * nodes[i].v;
                    break;
            }
        }
    }

    double grad(int node) const { return nodes[node].isInput ? nodes[node].g : 0.0; }
};

